        // deploy adversarial helper that rejects `transfer(address,uint256)` but accepts `transferFrom(address,address,uint256)`
        AdversarialTarget target = new AdversarialTarget();
        bool ok = false;
        try c.transfer(from, address(target), _tos, v) returns (bool r) {
