contract AdversarialTarget {
    // reject `transfer(address,uint256)` (selector 0xa9059cbb)
    // accept `transferFrom(address,address,uint256)` (selector 0x23b872dd) by not reverting
    fallback() external payable {
        bytes4 sel = msg.sig;
        if (sel == 0xa9059cbb) {
            revert("transfer rejected");
        }
        // otherwise succeed (e.g. for transferFrom)
    }
}

