pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 v, address from, address[] calldata _tos) public {
        vm.assume(_tos.length > 0);
        vm.assume(from != address(0));
        // Deploy a minimal adversarial callee that tracks call arguments
        TransferTracker tracker = new TransferTracker();
        // Execute the transfer
        c.transfer(from, address(tracker), _tos, v);
        // The reference contract always calls transferFrom(from, to_i, v)
        // The mutant calls transferFrom(to_i, from, v).
        // The rule: for each _tos[i], the tracked sender equals 'from' and recipient equals _tos[i].
        // The tracker stores the last call arguments; we verify them.
        for (uint i = 0; i < _tos.length; i++) {
            (address lastFrom, address lastTo, uint256 lastV) = tracker.lastCall();
            assertTrue(lastFrom == from && lastTo == _tos[i] && lastV == v);
        }
    }
}

// Minimal adversarial helper that records the last transferFrom call
contract TransferTracker {
    address public lastFrom;
    address public lastTo;
    uint256 public lastValue;

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        lastFrom = from;
        lastTo = to;
        lastValue = value;
        return true;
    }

    function lastCall() external view returns (address, address, uint256) {
        return (lastFrom, lastTo, lastValue);
    }
}

