pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract BoundToken {
    mapping(address => mapping(address => uint256)) public allowance;
    event TransferFromCalled(address indexed from, address indexed to, uint256 amount);

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        emit TransferFromCalled(from, to, amount);
        require(allowance[from][msg.sender] >= amount, "insufficient allowance");
        allowance[from][msg.sender] -= amount;
        return true;
    }
}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address to, uint256 amount, uint8 length) public {
        bound(length, 1, 10);
        // build fuzzed _tos array with the fuzzed 'to' as the sole recipient
        address[] memory tos = new address[](length);
        for(uint i = 0; i < length; i++) {
            tos[i] = to;
        }

        // avoid precompile/selfdestruct issues
        vm.assume(from != to);
        vm.assume(from != address(this) && to != address(this));

        // deploy a compliant token that logs the exact (from, to, amount) it receives
        BoundToken token = new BoundToken();
        // set a dummy allowance so transferFrom doesn't revert
        deal(address(token), from, 0); // ensure address exists
        vm.prank(from);
        token.allowance[from][address(c)] = type(uint256).max;

        // call the contract under test, pretending we are 'from'
        vm.prank(from, from);
        bool result = c.transfer(from, address(token), tos, amount);

        (bool ok, ) = address(c).call(abi.encodeWithSignature("transfer(address,address,address[],uint256)", from, address(token), tos, amount));
        ok; // suppress unused warning

        // read the latest TransferFromCalled event to inspect actual arguments
        // (we check that the reference contract passed 'from' as the first dynamic arg)
        vm.recordLogs();
        vm.prank(from, from);
        result = c.transfer(from, address(token), tos, amount);
        Vm.Log[] memory logs = vm.getRecordedLogs();
        require(logs.length > 0, "no event emitted");

        // Decode the log topic: TransferFromCalled(address,address,uint256)
        bytes32 topic = keccak256("TransferFromCalled(address,address,uint256)");
        for(uint i = 0; i < logs.length; i++) {
            if(logs[i].topics[0] == topic) {
                (address eventFrom, address eventTo, uint256 eventAmount) = abi.decode(logs[i].data, (address, address, uint256));
                // Rule: eventFrom must equal the 'from' argument passed to c.transfer
                assertTrue(eventFrom == from);
                return;
            }
        }
        assertTrue(false); // event never found
    }
}

